package io.coolbox.datastructures;
import com.sun.jna.ptr.IntByReference; import com.sun.jna.ptr.LongByReference; import io.coolbox.internal.NativeHandle; import java.util.OptionalLong;
/** Integer LSM key/value tree (Python: {@code data_structures.Int64LsmTree}). */
public final class Int64LsmTree extends NativeHandle {
 public Int64LsmTree(){this(64);} public Int64LsmTree(long threshold){super(DataStructuresNative.INSTANCE.coolbox_ds_lsm_new(threshold),DataStructuresNative.INSTANCE::coolbox_ds_lsm_free);} public void set(long k,long v){DataHandle.ok(DataStructuresNative.INSTANCE.coolbox_ds_lsm_put(handle(),k,v));} public OptionalLong get(long k){LongByReference v=new LongByReference();IntByReference f=new IntByReference();DataHandle.ok(DataStructuresNative.INSTANCE.coolbox_ds_lsm_get(handle(),k,v,f));return DataHandle.optional(v,f.getValue()!=0);} public boolean remove(long k){IntByReference r=new IntByReference();DataHandle.ok(DataStructuresNative.INSTANCE.coolbox_ds_lsm_remove(handle(),k,r));return DataHandle.changed(r);} public boolean contains(long k){return DataStructuresNative.INSTANCE.coolbox_ds_lsm_contains(handle(),k)!=0;} public void flush(){DataHandle.ok(DataStructuresNative.INSTANCE.coolbox_ds_lsm_flush(handle()));} public void compact(){DataHandle.ok(DataStructuresNative.INSTANCE.coolbox_ds_lsm_compact(handle()));} public void clear(){DataHandle.ok(DataStructuresNative.INSTANCE.coolbox_ds_lsm_clear(handle()));} public long size(){return DataStructuresNative.INSTANCE.coolbox_ds_lsm_size(handle());} public long memtableSize(){return DataStructuresNative.INSTANCE.coolbox_ds_lsm_memtable_size(handle());} public long sstableCount(){return DataStructuresNative.INSTANCE.coolbox_ds_lsm_sstable_count(handle());}
}
